CREATE TABLE cases(id INTEGER PRIMARY KEY, n INTEGER NOT NULL, input TEXT NOT NULL, expected TEXT NOT NULL); WITH RECURSIVE rng(k,s) AS (VALUES(0,1) UNION ALL SELECT k+1,(s*16807)%2147483647 FROM rng WHERE k<200001), draws(i,a,b,c,d) AS (SELECT (k-2)/4+1, max(CASE WHEN (k-2)%4=0 THEN s END), max(CASE WHEN (k-2)%4=1 THEN s END), max(CASE WHEN (k-2)%4=2 THEN s END), max(CASE WHEN (k-2)%4=3 THEN s END) FROM rng WHERE k BETWEEN 2 AND 200001 GROUP BY (k-2)/4), vals AS (SELECT i, a*100000/2147483647 AS x1, b*100000/2147483647+1000*(c*10000/2147483647) AS x2, d*8/2147483647+1 AS n FROM draws), parts AS (SELECT i,x1,n,substr(printf('%09d',x2),10-n) AS frac FROM vals) INSERT INTO cases(id,n,input,expected) SELECT i,n,printf('%d.%s4',x1,frac),printf('%d.%s',x1,frac) FROM parts;